    gen_random_uuid(),
    'b32f8d1e-12fa-db87-e8c6-44fda8f57064'::uuid,
    sp.id,
    -- mml_code = path末段(去{i}) + '_' + sp.id 前 8 hex
    --   保证 (command_id, mml_code) 唯一（path 末段可能重复，如多个 Enable）
    LEFT(
        COALESCE(
            (SELECT s FROM unnest(
                string_to_array(
                    regexp_replace(sp.standard_path, '\.$', ''),
                    '.'
                )
             ) WITH ORDINALITY AS x(s, ord)
             WHERE s !~ '\{i\}' AND s <> ''
             ORDER BY ord DESC LIMIT 1),
            'path'
        ) || '_' || SUBSTRING(REPLACE(sp.id::text, '-', '') FROM 1 FOR 8),
        100
    ),
    jsonb_build_object(
        'zh-CN', sp.standard_path,
        'en-US', sp.standard_path
    ),
    true,
    false,
    ROW_NUMBER() OVER (ORDER BY sp.standard_path) - 1
FROM standard_params sp
WHERE ((ARRAY(SELECT regexp_replace(s, '\{i\}', '', 'g') FROM unnest(string_to_array(sp.standard_path, '.')) AS s) && ARRAY['Wan3Config', 'Wan3']::text[])) AND LENGTH(sp.standard_path) - LENGTH(REPLACE(sp.standard_path, '.', '')) <= 5 AND sp.entry_type = 'parameter' AND COALESCE(sp.access, '') IN ('READ_WRITE', 'WRITE_ONLY')
ON CONFLICT (command_id, standard_path_id) DO NOTHING;

